// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {FlashGovernanceArbiter} from "../src/FlashGovernanceArbiter.sol";

contract InvMutTest is Test {
    FlashGovernanceArbiter c;

    function setUp() public {
        __InvMutHandleStub stub = new __InvMutHandleStub();
        stub.setFlashGoverner(address(stub));
        c = new FlashGovernanceArbiter(address(stub));
    }

    function testFuzz_property(
        address actor,
        address targetContract,
        address asset,
        uint256 amount,
        uint256 unlockTime
    ) public {
        // Widen admissible domain: actor must be a real non-zero caller, amount must be
        // positive (so a pending decision actually exists), and unlockTime strictly in
        // the future (the bug-triggering side of the comparison).
        vm.assume(actor != address(0));
        vm.assume(targetContract != address(0));
        amount = bound(amount, 1, type(uint128).max);
        unlockTime = bound(unlockTime, block.timestamp + 1, block.timestamp + 365 days);

        // Record a pending flash-governance decision for (targetContract, actor) with
        // a future unlock time.  assertGovernanceApproved requires the caller to be the
        // DAO or a governed address, and pulls in the configured asset.
        address dao = c.DAO();
        // asset must be a functioning ERC20 for transferFrom; actor must hold the tokens.
        __InvMutHandleStub token = new __InvMutHandleStub();
        token.mint(actor, amount);
        asset = address(token);

        vm.prank(dao);
        c.configureFlashGovernance(asset, amount, unlockTime, false);

        vm.prank(actor);
        token.approve(address(c), amount);

        vm.prank(dao);
        c.setGoverned(new address[](0), new bool[](0));

        // DAO calls assertGovernanceApproved with actor as sender of the tokens.
        // flashEnabled requires msg.sender == DAO.  It transfers amount from
        // `sender` (the fuzzed actor) into c and records a pending decision for
        // targetContract keyed by that sender.
        vm.prank(dao);
        c.assertGovernanceApproved(actor, targetContract, false);

        (uint256 recordedAmount, uint256 recordedUnlock, address recordedAsset, ) =
            c.pendingFlashDecision(targetContract, actor);

        // Precondition: a pending decision exists with the future unlock time.
        vm.assume(recordedAmount == amount);
        vm.assume(recordedUnlock > block.timestamp);

        // The fuzzed actor attempts to withdraw before unlock.
        vm.prank(actor);
        bool ok;
        try c.withdrawGovernanceAsset(targetContract, asset) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: with a future unlock time, the reference must reject the
        // withdrawal (ok == false) and the pending decision must survive unchanged.
        (uint256 postAmount, uint256 postUnlock, address postAsset, ) =
            c.pendingFlashDecision(targetContract, actor);

        bool referenceSatisfied = (!ok) && postAmount == amount && postUnlock == recordedUnlock && postAsset == asset;

        assertTrue(referenceSatisfied);
    }
}

contract __InvMutHandleStub {
    address public flashGoverner;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function setFlashGoverner(address g) external {
        flashGoverner = g;
    }

    function getFlashGoverner() external view returns (address) {
        return flashGoverner;
    }

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        uint256 allowed = allowance[from][msg.sender];
        if (allowed != type(uint256).max) {
            allowance[from][msg.sender] = allowed - amount;
        }
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function setEnforcement(bool) external {}

    function assertGovernanceApproved(address, address, bool) external {}

    function enforceToleranceInt(int256, int256) external view {}

    function enforceTolerance(uint256, uint256) external view {}

    function burnFlashGovernanceAsset(address, address, address, uint256) external {}

    function totalSupply() external pure returns (uint256) { return 0; }

    function configured() external pure returns (bool) { return false; }

    function successfulProposal(address) external pure returns (bool) { return false; }

    function proposalConfig() external view returns (uint256, uint256, address) {
        return (0, 0, address(this));
    }

    function domainConfig() external view returns (address, address, address, address, bool, address, address) {
        return (address(0), address(0), address(0), address(0), false, address(0), address(0));
    }

    function currentProposalState() external view returns (uint256, uint256, address, uint256, address) {
        return (0, 0, address(0), 0, address(0));
    }

